factors.formula_or_rule:
// 计算三个子信号（个股时间序列）
close_minus_open = adj_close - adj_open
std_abs_diff = rolling_stddev(abs(close_minus_open), window=5, min_periods=5)
corr_close_open = rolling_correlation(adj_close, adj_open, window=10, min_periods=10)

// 子信号截面标准化（逐日横截面 z-score 标准化，均值0标准差1）
z_std = zscore(std_abs_diff)
z_diff = zscore(close_minus_open)
z_corr = zscore(corr_close_open)

// 等权合成原始信号
raw = z_std + z_diff + z_corr

// 横截面去极值：MAD=5 截尾（中位数±5*MAD）

// 行业市值中性化：以去极值后的 raw 为因变量，对数总市值 log(total_market_cap) 和申万一级行业哑变量（drop_first）为自变量，做横截面 OLS 回归，取残差 s_neutral

// 截面排名：对 s_neutral 在每个交易日做升序排名（1 为最小，N 为最大）
rank_signal = cross_sectional_rank(s_neutral)

// 最终因子值
factor = -1 * rank_signal

// 因子值越大（接近 -1），表示原始 s_neutral 越小（低波动低趋势）；因子值越小（接近 -N），表示 s_neutral 越大（高波动高趋势）。
